/* OCS Heart Field Guide service worker. Generated by build.py: ocs-heart-e65ab7713629 is versioned by a content hash,
   so every rebuild produces a new worker + cache and the page shows "Update ready". No external network. */
'use strict';
const CACHE = 'ocs-heart-e65ab7713629';
const PREFIX = 'ocs-heart-';
const PRECACHE = ['./', './index.html', './manifest.webmanifest',
  './icon-180.png', './icon-192.png', './icon-512.png', './icon-512-maskable.png'];
const INDEX = new URL('./index.html', self.registration.scope).href;

self.addEventListener('install', e => {
  // fresh copies (bypass the HTTP cache); all-or-nothing so a half-cached install never activates
  e.waitUntil(caches.open(CACHE).then(c =>
    Promise.all(PRECACHE.map(u => c.add(new Request(u, {cache: 'reload'}))))));
  // intentionally no skipWaiting(): the page asks for it when the user taps "Update ready"
});

self.addEventListener('activate', e => {
  e.waitUntil((async () => {
    for (const k of await caches.keys()) if (k.startsWith(PREFIX) && k !== CACHE) await caches.delete(k);
    await self.clients.claim();
  })());
});

self.addEventListener('message', e => {
  const d = e.data;
  if (d === 'skipWaiting' || (d && d.type === 'skipWaiting')) self.skipWaiting();
});

self.addEventListener('fetch', e => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;          // never touch / cache cross-origin
  if (req.mode === 'navigate') {
    // app shell: always the cached index.html (query string / hash ignored); network only if cache is empty
    e.respondWith((async () => {
      const c = await caches.open(CACHE);
      return (await c.match(INDEX, {ignoreSearch: true})) || (await c.match('./', {ignoreSearch: true})) || fetch(req);
    })());
    return;
  }
  e.respondWith((async () => {
    const c = await caches.open(CACHE);
    const hit = await c.match(req);
    if (hit) return hit;
    const res = await fetch(req);
    if (res && res.ok && res.type === 'basic') c.put(req, res.clone()).catch(() => {});
    return res;
  })());
});
